\node[font=\fontsize{12}{14.4}\selectfont, left] at (E) {$E$};
\node[font=\fontsize{12}{14.4}\selectfont, right] at (F) {$F$};
\node[font=\fontsize{12}{14.4}\selectfont, above right] at (O) {$O$};
